import json

def parse_B_string(input_str):
    if input_str.startswith('('):
        parsed_parentheses, rest = parse_B_parentheses(input_str)
        if parsed_parentheses:
            return parse_B_string_rest(rest)
        else:
            return False, input_str
    elif input_str.startswith('a'):
        return parse_string_inside(input_str)
    elif input_str == '':
        return True, ''
    else:
        return False, input_str


def parse_B_string_rest(input_str):
    if input_str.startswith('('):
        parsed_parentheses, rest = parse_B_parentheses(input_str)
        if parsed_parentheses:
            return parse_B_string_rest(rest)
        else:
            return False, input_str
    elif input_str == '':
        return True, ''
    else:
        return False, input_str


def parse_B_parentheses(input_str):
    if input_str.startswith('('):
        parsed_inside, rest = parse_string_inside(input_str[1:])
        if parsed_inside and rest.startswith(')'):
            return True, rest[1:]
    elif input_str.startswith(')'):
        return True, input_str[1:]
    return False, input_str


def parse_string_inside(input_str):
    if input_str.startswith('a'):
        return parse_string_inside(input_str[1:])
    elif input_str.startswith('('):
        return parse_B_string(input_str[1:])
    elif input_str == '':
        return True, ''
    else:
        return False, input_str

def is_well_formed(input_str):
    stack = []
    for char in input_str:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack.pop() != '(':
                return False
    return len(stack) == 0

def predict_TDS(input_strings):
    results = {"balanced": [], "not_balanced": []}
    for string in input_strings:
        if string.count('(') != string.count(')'):
            results["not_balanced"].append(string)
            continue
        if is_well_formed(string):
            results["balanced"].append(string)
        else:
            results["not_balanced"].append(string)
    return results


def main(input_str):
    parsed, rest = parse_B_string(input_str)

    if parsed and rest == '':
        return True
    else:
        return False




